config..claude-plugin/plugin.json:
{
  "name": "firestore-native",
  "version": "0.3.4",
  "description": "Connect and interact with Firestore databases, collections, and documents.",
  "author": {
    "name": "Google LLC",
    "email": "data-cloud-ai-integrations@google.com"
  },
  "homepage": "https://cloud.google.com/firestore",
  "repository": "https://github.com/gemini-cli-extensions/firestore-native",
  "license": "Apache-2.0",
  "userConfig": {
    "firestore_project": {
      "title": "Project ID",
      "description": "ID of the Google Cloud project",
      "type": "string",
      "sensitive": false
    },
    "firestore_database": {
      "title": "Database ID",
      "description": "(Optional) ID of the Firestore database (Default: '(default)')",
      "type": "string",
      "sensitive": false
    }
  },
  "mcpServers": {
    "firestore": {
      "command": "npx",
      "args": [
        "-y",
        "@toolbox-sdk/server@1.9.0",
        "--prebuilt",
        "firestore",
        "--stdio"
      ],
      "env": {
        "FIRESTORE_PROJECT": "${user_config.firestore_project}",
        "FIRESTORE_DATABASE": "${user_config.firestore_database}"
      }
    }
  }
}
